using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using MyExpenseTracker.Api.Data;using MyExpenseTracker.Api.Models;namespace MyExpenseTracker.Api.Controllers;[Authorize,ApiController,Route("api/budgets")]public class BudgetsController(AppDbContext db):ControllerBase{[HttpGet]public async Task<IActionResult>Get(int year,int month)=>Ok(await db.Budgets.Where(x=>x.Year==year&&x.Month==month).OrderBy(x=>x.Category).ToListAsync());[HttpPost]public async Task<IActionResult>Save(Budget x){if(x.Month<1||x.Month>12||x.Amount<0)return BadRequest();var b=await db.Budgets.SingleOrDefaultAsync(y=>y.Year==x.Year&&y.Month==x.Month&&y.Category==x.Category);if(b==null){x.Id=0;db.Budgets.Add(x);}else b.Amount=x.Amount;await db.SaveChangesAsync();return Ok(b??x);}}